const toolCall = $input.first().json.body.message.toolCalls[0];
const fecha = toolCall.function.arguments.fecha;
const toolCallId = toolCall.id;
return [{ json: { fecha, toolCallId } }];

const fecha = $('Extraer Fecha y ID').first().json.fecha;
const toolCallId = $('Extraer Fecha y ID').first().json.toolCallId;

const [year, month, day] = fecha.split('-').map(Number);
const dateObj = new Date(year, month - 1, day);
const dow = dateObj.getDay(); // 0=domingo, 6=sabado

if (dow === 0) {
  return [{ json: { results: [{ toolCallId, result: 'El consultorio no atiende los domingos. Podés llamar de lunes a sábado.' }] } }];
}

// endMin: sabado=13:00=780, semana=21:00=1260
const endMin = dow === 6 ? 780 : 1260;
const allSlots = [];
for (let m = 480; m + 45 <= endMin; m += 45) {
  allSlots.push(
    String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0')
  );
}

const busyStates = ['PENDIENTE', 'CONFIRMADO', 'RECORDATORIO_ENVIADO'];
const occupied = $input.all()
  .filter(i => i.json.fecha === fecha && busyStates.includes(i.json.estado_turno))
  .map(i => i.json.hora);

const free = allSlots.filter(s => !occupied.includes(s));

const result = free.length === 0
  ? 'No hay turnos disponibles para el ' + fecha + '. ¿Querés que verifique otro día?'
  : 'Los horarios disponibles para el ' + fecha + ' son: ' + free.join(', ') + '. ¿Cuál preferís?';

return [{ json: { results: [{ toolCallId, result }] } }];
